      "what": "Co-sign the API contract as TWO OpenAPI documents with different lifecycles, not one: (1) browser-to-BFF, hand-authored with Zod and zod-openapi in the app repo, changing weekly - error envelope, tenant claim on every route and page_id on every query, pages list plus per-page connection-health and disconnect, Today feed (next-move with confidence, moves[], typed feed cards, setup-pill ingest progress), draft-score view-model carrying drivers[] in Saad's chip vocabulary plus confidence/coverage flag and band, unread counts, health (score, weekly delta, three factor sub-scores), nightly briefing aggregate, alerts (cited post/comment ids, one action, drafted reply, rules), best-times cells with a count-floor flag; (2) BFF-to-FastAPI, generated from Faheem's Pydantic models (N1-FH-19), changing when a model changes. Record which of the three owners owns each route (N1-AS-05), that only FastAPI holds warehouse credentials, and per route whether it is live or mock in N2 - the feature map gives Muteeb feed/aggregate endpoints that his own N2 list does not have, so the Today screen's data supply is settled here.",
