      "what": "Make every BFF route return the the relevant implementation envelope, and map every upstream failure to a stable code the front end can switch on: FastAPI timeout, model abstain, warehouse slow or unavailable, Meta token expired or revoked, rate-limited, ingest incomplete, page revoked. Put request_id in every response and every log line so a pilot's screenshot resolves to a trace. Nothing leaks a stack trace, a vendor message or a SQL error to the browser. Publish the code list to Saad the day it lands.",
      "why": "Saad's shared state components switch on these codes; if he has to parse message strings, every upstream wording change becomes a front-end bug, and the honest empty and abstain states silently degrade into generic errors.",
      "area": "App core",
      "due": "2026-10-21",
      "priority": "P1",
      "priority_reason": "P1 - real risk with slack inside N2, but the relevant implementation and every N3 surface depend on the published code list.",
