      "what": "Add the second callback the app dashboard requires: verify the signed_request, resolve the Facebook user and pages to tenant and page ids, revoke the stored tokens and mark those pages disconnected, then run the same cascade Filza's N2-MT-06 spec defines for deletion (or record why deauthorize retains and deletion purges, so the privacy policy stays true). Register the URL in the dashboard with the deletion callback and log every call.",
